from openpyxl.utils import get_column_letter

path='/root/data/workbook.xlsx'
wb = openpyxl.load_workbook(path)
for name in wb.sheetnames:
    print(f'=== Sheet: {name} ===')
    ws = wb[name]
    print(f'Dimensions: {ws.dimensions}; max_row={ws.max_row}; max_col={ws.max_column}')
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column, values_only=False):
        vals=[]
        for cell in row:
            if cell.value is not None:
                vals.append(f'{cell.coordinate}: {cell.value!r}')
        if vals:
            print('  ' + ' | '.join(vals))

print('\n=== Specific: Task D10:D31 ===')
ws=wb['Task']
for r in range(10,32):
    c=ws[f'D{r}']
    print(f'D{r}: value={c.value!r}, fill={c.fill.fill_type}/{c.fill.fgColor.type}:{c.fill.fgColor.rgb or c.fill.fgColor.indexed}')

print('\n=== Specific: Task H10:L10 years ===')
for c in range(8,13):
    cell=ws.cell(10,c)
    print(f'{cell.coordinate}: value={cell.value!r}, fill={cell.fill.fill_type}/{cell.fill.fgColor.type}:{cell.fill.fgColor.rgb or cell.fill.fgColor.indexed}')

print('\n=== Specific: Task A35:L50 values and fills ===')
for r in range(35,51):
    parts=[]
    for c in range(1,13):
        cell=ws.cell(r,c)
        val=cell.value
        fill=f'{cell.fill.fill_type}/{cell.fill.fgColor.type}:{cell.fill.fgColor.rgb or cell.fill.fgColor.indexed}'
        if val is not None or c>=8:
            parts.append(f'{cell.coordinate}={val!r} [fill {fill}]')
    print(' | '.join(parts))

print('\n=== Specific: Task H12:L17, H19:L24, H26:L31 values and fills ===')
for r1,r2 in [(12,17),(19,24),(26,31)]:
    for r in range(r1,r2+1):
        parts=[]
        for c in range(1,13):
            cell=ws.cell(r,c)
            if c<=7 or c>=8:
                fill=f'{cell.fill.fill_type}/{cell.fill.fgColor.type}:{cell.fill.fgColor.rgb or cell.fill.fgColor.indexed}'
                parts.append(f'{cell.coordinate}={cell.value!r}[{fill}]')
        print(' | '.join(parts))
    print('---')

print('\n=== Specific: Data rows 1 and 21:38 all columns ===')
ws=wb['Data']
for r in [1] + list(range(21,39)):
    parts=[]
    for c in range(1, ws.max_column+1):
